package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.*;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.research.*;
/** Complete native GOLEMANCY book traversal; no recipe placeholders or missing item/resource icons. */
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class GolemancyBookAudit {
 /** -Dtc4modern.bookCategory=ELDRITCH etc. reuses this traversal for another tab. */
 static final String CATEGORY=System.getProperty("tc4modern.bookCategory","GOLEMANCY");
 static int ticks,index,spread,bookStart;static volatile boolean ready;static List<ResearchItem> entries;static ThaumonomiconScreen book;static int recipes,pages;
 static final java.util.Set<String> missing=new java.util.TreeSet<>();
 /** Records instead of throwing so one traversal lists every missing golemancy recipe page. */
 static boolean missing(String research,String recipe){if(!Boolean.getBoolean("tc4modern.golemancyBookAuditOnly"))return false;missing.add(research+"/"+recipe);return true;}
 static void check(boolean value,String message){if(!value&&!CATEGORY.equals("GOLEMANCY")&&!message.startsWith("no missing")){missing.add("CHECK:"+message);System.out.println("TC4_GOLEMANCY_BOOK SOFTFAIL "+message);return;}if(!value)throw new IllegalStateException("TC4_GOLEMANCY_BOOK FAIL "+message);System.out.println("TC4_GOLEMANCY_BOOK PASS "+message);}
 static void validate(Minecraft mc){thaumcraft.common.config.ConfigResearchData.init();entries=new ArrayList<>(ResearchCategories.getResearchList(CATEGORY).research.values());if(CATEGORY.equals("GOLEMANCY"))check(entries.size()==39,"all 39 original golemancy researches count="+entries.size());else System.out.println("TC4_GOLEMANCY_BOOK category "+CATEGORY+" entries="+entries.size());for(var r:entries){var icon=BasicsBookRecipes.researchIcon(r.key);if(icon!=null){check(!icon.stack().isEmpty()||icon.texture()!=null||icon.model()!=null,"nonempty icon "+r.key);if(icon.model()!=null)check(mc.getModelManager().getModel(BookDisplayModels.id(icon.model()))!=mc.getModelManager().getMissingModel(),"actual block model "+r.key);if(!icon.stack().isEmpty())check(mc.getItemRenderer().getModel(icon.stack(),mc.level,mc.player,0)!=mc.getModelManager().getMissingModel(),"actual item model "+r.key);else if(icon.texture()!=null)check(mc.getResourceManager().getResource(AlchemyContent.id(icon.texture())).isPresent(),"sprite icon "+r.key);}else check(r.icon_resource!=null&&!r.icon_resource.getPath().contains("_unknown")&&mc.getResourceManager().getResource(r.icon_resource).isPresent(),"original research icon "+r.key);check(!Component.translatable("tc.research_name."+r.key).getString().startsWith("tc.research_name."),"translated name "+r.key);for(var page:r.getPages()){pages++;if(page.recipeKey!=null)recipes++;else if(page.type!=ResearchPage.PageType.ASPECTS)check(!page.getTranslatedText().startsWith("tc.research_page."),"translated page "+r.key);}}check(CATEGORY.equals("GOLEMANCY")?recipes>=36:recipes>0,"actual recipe pages count="+recipes);}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.golemancyBookAuditOnly"))return;var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;if(ticks==80){var server=mc.getSingleplayerServer();var id=mc.player.getUUID();server.execute(()->{var p=server.getPlayerList().getPlayer(id);for(var cat:ResearchCategories.researchCategories.values())for(var r:cat.research.values())DevCommands.grant(p.getPersistentData(),r.key,new HashSet<>());ThaumometerItem.sync(p,"");ready=true;});}if(ticks==120){check(ready,"all research granted server side");validate(mc);mc.setScreen(new Grid());}if(ticks==130)LiquidDeathAudit.shot(mc,CATEGORY.toLowerCase(java.util.Locale.ROOT)+"-all-icons.png");if(ticks==140){var inv=mc.player.getInventory();book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,Component.empty());book.auditBrowser(CATEGORY,-3,1);mc.setScreen(book);}if(ticks==150)LiquidDeathAudit.shot(mc,"golemancy-browser-top.png");if(ticks==160)book.auditBrowser(CATEGORY,-2,7);if(ticks==170)LiquidDeathAudit.shot(mc,"golemancy-browser-bottom.png");if(ticks==180){bookStart=ticks;book.auditOpen(entries.get(0),0);}if(ticks>=180&&(ticks-180)%10==5){var research=entries.get(index);LiquidDeathAudit.shot(mc,String.format(java.util.Locale.ROOT,CATEGORY.toLowerCase(java.util.Locale.ROOT)+"-page-%02d-%s-%02d.png",index,research.key,spread));spread+=2;if(spread>=book.auditPageCount()){System.out.println("TC4_GOLEMANCY_BOOK RENDERED "+research.key+" pages="+book.auditPageCount());spread=0;index++;if(index>=entries.size()){check(missing.isEmpty(),"no missing recipe pages "+missing);System.out.println("TC4_GOLEMANCY_BOOK ALL PASS pages="+pages+" recipes="+recipes);mc.stop();return;}}book.auditOpen(entries.get(index),spread);}}
 static final class Grid extends Screen {
  Grid(){super(Component.literal("GOLEMANCY"));}
  @Override public boolean isPauseScreen(){return false;}
  @Override public void render(GuiGraphics gui,int mouseX,int mouseY,float partial){gui.fill(0,0,width,height,0xff1d1724);gui.drawCenteredString(font,"Големостроение — все исследования",width/2,8,0xffffff);BasicsBookRecipes.begin();for(int i=0;i<entries.size();i++){var r=entries.get(i);int x=8+(i%8)*(width-16)/8,y=28+(i/8)*(height-35)/7;var icon=BasicsBookRecipes.researchIcon(r.key);if(icon!=null)BasicsBookRecipes.icon(gui,icon,x+20,y);else gui.blit(r.icon_resource,x+20,y,0,0,16,16,16,16);String name=Component.translatable("tc.research_name."+r.key).getString();gui.drawString(font,font.plainSubstrByWidth(name,(width-20)/8-2),x,y+19,0xd5c6e7,false);}}}
}
